def parse_map_arguments(values: Iterable[str]) -> dict[str, ToonIndex]:
    result: dict[str, ToonIndex] = {}
    for value in values:
        if "=" not in value:
            raise EcosystemError(f"--map must use ORGANIZATION=PATH, got {value!r}")
        organization, raw_path = value.split("=", 1)
        organization = organization.strip()
        if not organization:
            raise EcosystemError("--map organization cannot be empty")
        index = parse_toon_index(Path(raw_path))
        if index.organization != "unknown" and index.organization != organization:
            raise EcosystemError(
                f"Map {raw_path} declares organization {index.organization!r}, expected {organization!r}"
            )
        result[organization] = index
    return result

def evaluate_condition(condition: Json, state: Json) -> bool:
    if "all" in condition:
        return all(evaluate_condition(item, state) for item in condition["all"])
    if "any" in condition:
        return any(evaluate_condition(item, state) for item in condition["any"])
    if "not" in condition:
        return not evaluate_condition(condition["not"], state)
    if "metric" in condition:
        actual = metric_value(state, condition["metric"])
        return compare(actual, condition["op"], condition["value"])
    if "fact" in condition:
        actual = get_path(state.get("facts", {}), condition["fact"])
        return compare(actual, condition["op"], condition["value"])
    raise PolicyError(f"Invalid condition: {condition!r}")

